var t=[{title:`Pourquoi les liquides comptent`,text:`Votre corps utilise l’eau pour transporter les nutriments, faire circuler le sang, réguler la température et remplacer ce que vous perdez en transpirant. Même une légère déshydratation peut rendre un exercice intense plus difficile, surtout par temps chaud. Aucune quantité unique ne convient à tous les sportifs ni à toutes les séances.`},{title:`Avant et pendant une séance`,text:`Commencez raisonnablement bien hydraté et gardez de l’eau à portée de main, surtout pour les séances longues ou chaudes. Pour les séances courtes ordinaires, boire quand vous avez soif suffit souvent. La chaleur, une longue activité intense et une transpiration inhabituellement abondante peuvent justifier un plan d’hydratation personnel. Remplacer les électrolytes peut compter lors d’un exercice long, mais une courte séance en salle n’en a pas automatiquement besoin. Si la chaleur rend une séance dangereuse, entraînez-vous moins ou allez dans un endroit plus frais.`},{title:`Boire trop`,text:`Boire de grandes quantités sans tenir compte de la soif ou de la perte de sueur peut diluer le sodium de votre sang et provoquer une hyponatrémie liée à l’exercice. Prendre du poids pendant une longue épreuve d’endurance peut être un signe que vous buvez trop. Un violent mal de tête, une confusion ou des vomissements pendant un exercice prolongé nécessitent une évaluation médicale urgente. Boire davantage n’est pas la solution.`},{title:`Repères simples`,text:`La soif, les variations de poids corporel autour des longues séances, la météo et la durée de votre entraînement peuvent tous guider la quantité à boire. La couleur des urines donne un indice approximatif, mais ce n’est pas un test diagnostique. Si vous avez une maladie rénale ou cardiaque, demandez à votre médecin un conseil adapté à votre situation.`}];var s=[{label:`NATA : remplacement des liquides chez les personnes physiquement actives`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC5634236/`},{label:`Wilderness Medical Society : hyponatrémie liée à l’exercice`,url:`https://journals.sagepub.com/doi/full/10.1016/j.wem.2019.11.003`}];var u={sections:t,sources:s};export{u as default,t as sections,s as sources};